cat > merge.py <<'EOF'
import json
import pandas as pd

SOURCES = [
    ("source_a", lambda: pd.read_json("/data/source_a/users.json", dtype=False)),
    ("source_b", lambda: pd.read_csv("/data/source_b/users.csv", dtype=str, keep_default_na=False)),
    ("source_c", lambda: pd.read_parquet("/data/source_c/users.parquet")),
]
ALIASES = {
    "user_id": ["user_id", "id", "userId"],
    "email": ["email", "email_address"],
    "name": ["full_name", "name", "userName"],
    "created_date": ["registration_date", "created_at", "joined"],
    "status": ["status", "is_active", "active"],
}
FIELDS = ["name", "email", "created_date", "status"]


def blank(v):
    return v is None or (isinstance(v, float) and pd.isna(v)) or (isinstance(v, str) and not v.strip())


def norm_date(v):
    if blank(v):
        return None
    if isinstance(v, (int, float)):
        return pd.to_datetime(v, unit="s" if v < 1e11 else "ms").strftime("%Y-%m-%d")
    return pd.to_datetime(str(v).strip()).strftime("%Y-%m-%d")


def norm_status(v):
    if blank(v):
        return None
    if isinstance(v, bool) or str(v).strip().lower() in ("true", "false", "1", "0", "yes", "no"):
        truthy = v if isinstance(v, bool) else str(v).strip().lower() in ("true", "1", "yes")
        return "active" if truthy else "inactive"
    return str(v).strip()


NORMALIZE = {
    "name": lambda v: None if blank(v) else str(v).strip(),
    "email": lambda v: None if blank(v) else str(v).strip(),
    "created_date": norm_date,
    "status": norm_status,
}


def load(read):
    df = read()
    records = {}
    for row in df.to_dict("records"):
        rec = {}
        for field, names in ALIASES.items():
            col = next((n for n in names if n in row), None)
            rec[field] = row[col] if col else None
        if blank(rec["user_id"]):
            continue
        uid = int(float(rec.pop("user_id")))
        records[uid] = {f: NORMALIZE[f](rec[f]) for f in FIELDS}
    return records


by_source = [(name, load(read)) for name, read in SOURCES]
merged, conflicts = [], []
for uid in sorted({u for _, recs in by_source for u in recs}):
    row = {"user_id": uid}
    for field in FIELDS:
        values = {s: recs[uid][field] for s, recs in by_source if uid in recs and recs[uid][field] is not None}
        selected = next(iter(values.values()), None)
        row[field] = selected
        if len(set(values.values())) > 1:
            conflicts.append({"user_id": uid, "field": field, "values": values, "selected": selected})
    merged.append(row)

out = pd.DataFrame(merged, columns=["user_id"] + FIELDS)
out["user_id"] = out["user_id"].astype("int64")
for f in FIELDS:
    out[f] = out[f].astype("string")
out.to_parquet("/app/merged_users.parquet", index=False)
with open("/app/conflicts.json", "w") as fh:
    json.dump({"total_conflicts": len(conflicts), "conflicts": conflicts}, fh, indent=2)
print(out.to_string())
print(json.dumps(conflicts, indent=1))
EOF
./envcp ./merge.py :/app/merge.py && ./envrun 'python3 /app/merge.py && python3 -c "import pyarrow.parquet as pq; print(pq.read_schema(\"/app/merged_users.parquet\"))"'
